import React, { useEffect, useState } from 'react';
import api from '../services/api';

const MotoristasList = () => {
    const [motoristas, setMotoristas] = useState([]);
    const [erro, setErro] = useState('');
    const [editando, setEditando] = useState(null);
    const [novoNome, setNovoNome] = useState('');

    useEffect(() => {
        buscarMotoristas();
    }, []);

    const buscarMotoristas = async () => {
        try {
            const response = await api.get('/motoristas/listar');
            setMotoristas(response.data);
        } catch (err) {
            setErro('Erro ao buscar motoristas.');
        }
    };

    const excluirMotorista = async (id) => {
        if (!window.confirm('Tem certeza que deseja excluir este motorista?')) return;

        try {
            await api.delete(`/motoristas/excluir/${id}`);
            buscarMotoristas(); // Atualiza a lista após a exclusão
        } catch (err) {
            setErro('Erro ao excluir motorista.');
        }
    };

    const editarMotorista = async (id) => {
        try {
            await api.put(`/motoristas/editar/${id}`, { nome: novoNome });
            setEditando(null); // Para sair do modo de edição
            buscarMotoristas(); // Atualiza a lista
        } catch (err) {
            setErro('Erro ao editar motorista.');
        }
    };

    return (
        <div>
            <h2>📋 Lista de Motoristas</h2>
            {erro && <p>{erro}</p>}
            <ul>
                {motoristas.map((motorista) => (
                    <li key={motorista.id}>
                        {editando === motorista.id ? (
                            <>
                                <input
                                    type="text"
                                    value={novoNome}
                                    onChange={(e) => setNovoNome(e.target.value)}
                                />
                                <button onClick={() => editarMotorista(motorista.id)}>💾 Salvar</button>
                            </>
                        ) : (
                            <>
                                {motorista.nome} - {motorista.placa} ({motorista.modelo})
                                <button onClick={() => setEditando(motorista.id)}>✏️ Editar</button>
                                <button onClick={() => excluirMotorista(motorista.id)}>🗑️ Excluir</button>
                            </>
                        )}
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default MotoristasList;
